body {
  /* Apply font kerning globally for enhanced default readability */
  font-kerning: normal;
}

h1, .display-text {
  /* Ensure optimal letter spacing for prominent headings and titles */
  font-kerning: normal;
  /* Optional: Micro-adjustments can further refine visual harmony */
  letter-spacing: -0.02em;
}

/* In rare cases where kerning is undesired (e.g., specific artistic effects) */
.no-kerning-example {
  font-kerning: none;
}
